if(($_GET['action']??'')==='lang' && isset($_SESSION['user'])){ $lang=($_GET['lang']??'es')==='en'?'en':'es'; $_SESSION['lang']=$lang; try{appDb()->prepare('UPDATE users SET locale=? WHERE id=?')->execute([$lang,$_SESSION['user']['id']]); $_SESSION['user']['locale']=$lang;}catch(Throwable $e){} header('Location: ?page='.urlencode($_GET['page']??'dashboard')); exit; }
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='login') {
  try{$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$st=appDb()->prepare("SELECT u.id,u.name,u.email,u.avatar_path,u.password_hash,u.locale,tu.tenant_id,tu.role_code,t.name company,t.status tenant_status FROM users u JOIN tenant_users tu ON tu.user_id=u.id JOIN tenants t ON t.id=tu.tenant_id WHERE u.email=? AND u.status='active' LIMIT 1");$st->execute([$email]);$u=$st->fetch();if(!$u||!password_verify($pass,$u['password_hash']))throw new RuntimeException('Correo o contraseña incorrectos.');if(in_array($u['tenant_status'],['suspended','closed'],true))throw new RuntimeException('La empresa no está habilitada para ingresar.');session_regenerate_id(true);unset($_SESSION['install_owner_email'],$_SESSION['registration_login_email']);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'avatar_path'=>$u['avatar_path']??null,'tenant_id'=>(int)$u['tenant_id'],'company'=>$u['company'],'role'=>$u['role_code'],'locale'=>$u['locale']];appDb()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);
    $ip=$_SERVER['REMOTE_ADDR']??'';$ua=substr($_SERVER['HTTP_USER_AGENT']??'',0,500);
    if(isset($_POST['remember'])){
