      setcookie('zynko_remember',$sid.'.'.$tok,['expires'=>time()+2592000,'path'=>'/','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','httponly'=>true,'samesite'=>'Lax']);
    }else{
