function jsonOut(bool $ok,string $message,array $data=[]): never {
  if($ok && $_SERVER['REQUEST_METHOD']==='POST' && isset($_SESSION['user'])){try{zynkoNotifyAdministrativeAction((string)($_POST['action']??''),$message,$data);}catch(Throwable $e){}}
  header('Content-Type: application/json; charset=utf-8'); echo json_encode(['ok'=>$ok,'message'=>$message,'data'=>$data],JSON_UNESCAPED_UNICODE); exit;
}
function uuid4(): string { $d=random_bytes(16);$d[6]=chr((ord($d[6])&0x0f)|0x40);$d[8]=chr((ord($d[8])&0x3f)|0x80);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($d),4)); }
function encryptSecret(string $plain): ?string { if($plain==='')return null; global $root;$e=envConfig($root.'/.env');$hex=$e['APP_KEY']??'';if(!preg_match('/^[a-f0-9]{64}$/i',$hex))throw new RuntimeException('APP_KEY inválida.');$iv=random_bytes(12);$tag='';$c=openssl_encrypt($plain,'aes-256-gcm',hex2bin($hex),OPENSSL_RAW_DATA,$iv,$tag);if($c===false)throw new RuntimeException('No se pudo cifrar.');return 'enc:v1:'.base64_encode($iv.$tag.$c); }
function zynkoLegalPlainToHtml(string $text): string {
  $text=trim($text);if($text==='')return '';
  $out='';foreach(preg_split('/\R{2,}/u',$text)?:[] as $block){$block=trim($block);if($block==='')continue;$lines=preg_split('/\R/u',$block)?:[];$first=trim((string)array_shift($lines));$rest=trim(implode("\n",$lines));if(preg_match('/^([0-9]+[.)]|[A-ZÁÉÍÓÚÑ][.)])\s+(.+)$/u',$first)){$out.='<h3>'.htmlspecialchars($first,ENT_QUOTES,'UTF-8').'</h3>';if($rest!=='')$out.='<p>'.nl2br(htmlspecialchars($rest,ENT_QUOTES,'UTF-8')).'</p>';}else{$whole=trim($first.($rest!==''?"\n".$rest:''));if($whole!=='')$out.='<p>'.nl2br(htmlspecialchars($whole,ENT_QUOTES,'UTF-8')).'</p>';}}
  return $out;
}
function zynkoSanitizeLegalHtml(string $html): string {
  $html=trim($html);if($html==='')return '';
  if($html===strip_tags($html))return zynkoLegalPlainToHtml($html);
  if(!class_exists('DOMDocument')){
    $clean=strip_tags($html,'<p><br><strong><b><em><i><u><h2><h3><h4><ul><ol><li><blockquote><a><hr>');
    return preg_replace_callback("/<\\s*(\\/?)\\s*([a-z0-9]+)([^>]*)>/i",function($m){
      $closing=$m[1]==='/';$tag=strtolower($m[2]);$void=in_array($tag,['br','hr'],true);
      if($closing)return $void?'':'</'.$tag.'>';
      $attrs='';
      if($tag==='a'&&preg_match("/href\\s*=\\s*([\\\"'])(.*?)\\1/i",$m[3],$hm)&&preg_match('#^(https?://|mailto:|tel:|/)#i',trim($hm[2])))$attrs.=' href="'.htmlspecialchars(trim($hm[2]),ENT_QUOTES,'UTF-8').'" target="_blank" rel="noopener noreferrer"';
      if(preg_match("/style\\s*=\\s*([\\\"'])(text-align\\s*:\\s*(left|center|right|justify)\\s*;?)\\1/i",$m[3],$sm))$attrs.=' style="'.htmlspecialchars($sm[2],ENT_QUOTES,'UTF-8').'"';
      return '<'.$tag.$attrs.'>';
    },$clean)??'';
  }
  $allowed=['p','br','strong','b','em','i','u','h2','h3','h4','ul','ol','li','blockquote','a','hr'];
  $dom=new DOMDocument('1.0','UTF-8');$prev=libxml_use_internal_errors(true);$dom->loadHTML('<?xml encoding="utf-8" ?><div id="zynko-legal-root">'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);libxml_clear_errors();libxml_use_internal_errors($prev);
  $rootNode=$dom->getElementById('zynko-legal-root');if(!$rootNode)return '';
  $walk=function($node) use (&$walk,$allowed){foreach(iterator_to_array($node->childNodes) as $child){if($child->nodeType===XML_ELEMENT_NODE){$tag=strtolower($child->nodeName);if(!in_array($tag,$allowed,true)){$frag=$child->ownerDocument->createDocumentFragment();while($child->firstChild)$frag->appendChild($child->firstChild);$child->parentNode->replaceChild($frag,$child);continue;}if($child->hasAttributes()){foreach(iterator_to_array($child->attributes) as $attr){$name=strtolower($attr->name);$value=trim($attr->value);$keep=false;if($tag==='a'&&$name==='href'&&preg_match('#^(https?://|mailto:|tel:|/)#i',$value))$keep=true;if($name==='style'&&preg_match('/^text-align\s*:\s*(left|center|right|justify)\s*;?$/i',$value))$keep=true;if(!$keep)$child->removeAttribute($attr->name);}if($tag==='a'&&$child->hasAttribute('href')){$child->setAttribute('target','_blank');$child->setAttribute('rel','noopener noreferrer');}}$walk($child);}}};$walk($rootNode);
  $out='';foreach($rootNode->childNodes as $child)$out.=$dom->saveHTML($child);return trim($out);
}
function zynkoLegalContentToHtml(string $content): string { return zynkoSanitizeLegalHtml($content); }

function mainTenantId(): int { try{return (int)appDb()->query('SELECT MIN(id) FROM tenants')->fetchColumn();}catch(Throwable $e){return 0;} }
function isPlatformOwner(): bool { return isset($_SESSION['user']) && (int)$_SESSION['user']['tenant_id']===mainTenantId() && in_array($_SESSION['user']['role']??'', ['owner','admin'],true); }
function zynkoIsImpersonating(): bool { return !empty($_SESSION['zynko_platform_context']['user']) && is_array($_SESSION['zynko_platform_context']['user']); }
function zynkoPlatformAudit(PDO $pdo,string $action,?int $tenantId=null,?int $userId=null,array $details=[]): void { try{$pdo->prepare('INSERT INTO platform_admin_audit(admin_user_id,tenant_id,target_user_id,action,details_json,ip_address,created_at) VALUES(?,?,?,?,?,?,NOW())')->execute([(int)($_SESSION['zynko_platform_context']['user']['id']??$_SESSION['user']['id']??0),$tenantId,$userId,$action,json_encode($details,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),mb_substr((string)($_SERVER['REMOTE_ADDR']??''),0,64)]);}catch(Throwable $e){} }
function zynkoUniqueTenantSlug(PDO $pdo,string $name): string { $v=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$name)?:$name;$base=strtolower($v);$base=trim((string)preg_replace('/[^a-z0-9]+/','-',$base),'-');if($base==='')$base='empresa';$base=mb_substr($base,0,95);$slug=$base;$q=$pdo->prepare('SELECT 1 FROM tenants WHERE slug=? LIMIT 1');for($i=0;$i<20;$i++){ $q->execute([$slug]);if(!$q->fetchColumn())return $slug;$slug=$base.'-'.substr(bin2hex(random_bytes(3)),0,6);}return $base.'-'.time(); }
function zynkoPlatformAdminEmail(PDO $pdo): string { try{$tid=mainTenantId();$q=$pdo->prepare("SELECT u.email FROM users u JOIN tenant_users tu ON tu.user_id=u.id WHERE tu.tenant_id=? AND u.status='active' ORDER BY tu.is_owner DESC,FIELD(tu.role_code,'owner','admin','supervisor','agent'),u.id LIMIT 1");$q->execute([$tid]);$v=trim((string)($q->fetchColumn()?:''));return filter_var($v,FILTER_VALIDATE_EMAIL)?$v:'';}catch(Throwable $e){return '';}}
function zynkoTenantOwner(PDO $pdo,int $tenantId): array { try{$q=$pdo->prepare("SELECT u.id,u.name,u.email,t.name company FROM tenant_users tu JOIN users u ON u.id=tu.user_id JOIN tenants t ON t.id=tu.tenant_id WHERE tu.tenant_id=? AND u.status='active' ORDER BY tu.is_owner DESC,FIELD(tu.role_code,'owner','admin','supervisor','agent'),u.id LIMIT 1");$q->execute([$tenantId]);return $q->fetch()?:[];}catch(Throwable $e){return [];}}
function zynkoNotifyAdministrativeAction(string $action,string $resultMessage,array $data=[]): void {
  /*
   * Central transactional audit mail for material configuration/account changes.
   * Deliberately excludes high-frequency operational activity (chat messages,
   * assignments, notes, searches, preferences and read-only/test actions) to
   * keep notifications useful instead of turning them into spam.
   */
  $catalog=[
    'company_create'=>['Empresa creada','Se creó una nueva empresa y su acceso principal en ZYNKO.','companies'],
    'company_update'=>['Empresa actualizada','Se actualizaron los datos o el estado de la empresa.','companies'],
    'company_user_manage'=>['Acceso de usuario actualizado','Se modificó el rol o estado de un usuario de la empresa.','users'],
    'company_user_temp_password'=>['Acceso restablecido','Se generó una contraseña temporal y se cerraron las sesiones anteriores del usuario.','users'],
    'company_impersonate'=>['Modo asistencia iniciado','El administrador principal inició una sesión de asistencia sobre la empresa.','companies'],
    'tenant_ai_save'=>['Configuración de NIVO IA actualizada','Se actualizaron las preferencias de NIVO IA de la empresa.','chatbot'],
    'api_key_create'=>['Clave API creada','Se creó una nueva credencial API para integraciones externas. La clave secreta no se incluye en este correo.','integrations'],
    'api_key_revoke'=>['Clave API revocada','Se revocó una credencial API de la empresa.','integrations'],
    'integration_save'=>['Integración creada','Se registró una nueva integración/webhook. El secreto de firma no se incluye en este correo.','integrations'],
    'settings_save'=>['Configuración de empresa actualizada','Se actualizaron datos, marca o preferencias generales de la empresa.','settings'],
    'webchat_widget_save'=>['NIVO Web Chat actualizado','Se modificó la configuración del widget NIVO Web Chat.','channels'],
    'webchat_installation_add'=>['Sitio NIVO autorizado','Se autorizó un nuevo dominio para utilizar NIVO Web Chat.','channels'],
    'webchat_installation_update'=>['Sitio NIVO actualizado','Se actualizaron los datos de un dominio autorizado para NIVO Web Chat.','channels'],
    'webchat_installation_toggle'=>['Estado de sitio NIVO actualizado','Se cambió el estado de una instalación autorizada de NIVO Web Chat.','channels'],
    'webchat_installation_delete'=>['Sitio NIVO desautorizado','Se eliminó la autorización de un dominio para NIVO Web Chat.','channels'],
    'bot_save'=>['NIVO actualizado','Se modificó la configuración principal del asistente NIVO.','chatbot'],
    'nivo_rule_add'=>['Regla de NIVO creada','Se agregó una nueva regla de automatización/conocimiento para NIVO.','chatbot'],
    'nivo_rule_update'=>['Regla de NIVO actualizada','Se modificó una regla de NIVO.','chatbot'],
    'nivo_rule_delete'=>['Regla de NIVO eliminada','Se eliminó una regla de NIVO.','chatbot'],
    'nivo_solution_add'=>['Solución de NIVO creada','Se agregó una solución al catálogo de conocimiento de NIVO.','chatbot'],
    'nivo_module_add'=>['Módulo de NIVO creado','Se agregó un módulo a una solución de NIVO.','chatbot'],
    'knowledge_approve'=>['Conocimiento de NIVO publicado','Se aprobó y publicó una fuente de conocimiento para NIVO.','chatbot'],
    'knowledge_file_add'=>['Archivo de conocimiento agregado','Se importó una nueva fuente de conocimiento para NIVO.','chatbot'],
    'knowledge_delete'=>['Conocimiento de NIVO eliminado','Se eliminó una fuente de conocimiento de NIVO.','chatbot'],
    'knowledge_add'=>['Conocimiento de NIVO agregado','Se agregó y publicó una nueva fuente de conocimiento.','chatbot'],
  ];
  if(!isset($catalog[$action]))return;
  $pdo=appDb();$platformTid=mainTenantId();if($platformTid<=0)return;
  [$title,$description,$page]=$catalog[$action];
  $targetTid=(int)($_POST['tenant_id']??($data['tenant_id']??($_SESSION['user']['tenant_id']??0)));
  if($action==='company_create')$targetTid=(int)($data['tenant_id']??0);
  if($targetTid<=0)$targetTid=(int)($_SESSION['user']['tenant_id']??0);
  $owner=$targetTid>0?zynkoTenantOwner($pdo,$targetTid):[];
  $company=(string)($owner['company']??($_SESSION['user']['company']??'Empresa'));
  $actor=(string)($_SESSION['user']['name']??'Usuario autorizado');
  $detail=$description."\n\nResultado: ".$resultMessage."\nEmpresa: ".$company."\nRealizado por: ".$actor."\nFecha: ".date('d/m/Y H:i');
  require_once $GLOBALS['root'].'/app/Services/NotificationService.php';$ns=new NotificationService($pdo,$GLOBALS['root']);
  $recipients=[];
  $customerMail=trim((string)($owner['email']??''));$customerAlreadyHandled=in_array($action,['channel_save'],true);if(!$customerAlreadyHandled&&filter_var($customerMail,FILTER_VALIDATE_EMAIL))$recipients[$customerMail]='customer';
  $adminMail=zynkoPlatformAdminEmail($pdo);if(filter_var($adminMail,FILTER_VALIDATE_EMAIL))$recipients[$adminMail]=isset($recipients[$adminMail])?'both':'admin';
  foreach($recipients as $to=>$kind){
    $subjectTitle=$kind==='admin'?'Control ZYNKO · '.$title:$title;
    $ns->sendAdministrativeEvent($platformTid,$to,$subjectTitle,$detail,['event'=>'admin_action','action'=>$action,'tenant_id'=>$targetTid,'audience'=>$kind,'page'=>$page]);
  }
}

function zynkoSubscriptionStatusLabel(string $status): string { return ['active'=>'Activo','grace'=>'Período de gracia','suspended'=>'Suspendido','cancelled'=>'Cancelado','trial'=>'Prueba'][$status]??ucfirst($status); }
function zynkoPublicSettings(PDO $pdo): array { try{$q=$pdo->query("SELECT setting_key,setting_value FROM system_settings WHERE setting_key LIKE 'public_%'");$out=[];foreach($q->fetchAll() as $row)$out[(string)$row['setting_key']]=(string)$row['setting_value'];return $out;}catch(Throwable $e){return [];} }
function zynkoVerifyPublicTurnstile(PDO $pdo,string $token,string $ip=''): void {
  $cfg=zynkoPublicSettings($pdo);
  if(($cfg['public_turnstile_enabled']??'0')!=='1')return;
  $secretRaw=trim((string)($cfg['public_turnstile_secret']??''));
  $secret=str_starts_with($secretRaw,'enc:v1:')?decryptSecret($secretRaw):$secretRaw;
  if($secret==='')throw new RuntimeException('La protección anti-spam no está configurada correctamente.');
  $token=trim($token);if($token==='')throw new RuntimeException('No se pudo validar que eres una persona. Intenta nuevamente.');
  $payload=['secret'=>$secret,'response'=>$token,'idempotency_key'=>uuid4()];if($ip!=='')$payload['remoteip']=$ip;
  $raw='';
  if(function_exists('curl_init')){
    $ch=curl_init('https://challenges.cloudflare.com/turnstile/v0/siteverify');
    curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>12,CURLOPT_HTTPHEADER=>['Content-Type: application/x-www-form-urlencoded'],CURLOPT_POSTFIELDS=>http_build_query($payload)]);
    $raw=(string)curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$err=(string)curl_error($ch);curl_close($ch);
    if($raw===''||$http<200||$http>=300)throw new RuntimeException('No pudimos completar la validación anti-spam. Intenta nuevamente.');
  }else{
    $ctx=stream_context_create(['http'=>['method'=>'POST','header'=>"Content-Type: application/x-www-form-urlencoded\r\n",'content'=>http_build_query($payload),'timeout'=>12,'ignore_errors'=>true]]);
    $raw=(string)@file_get_contents('https://challenges.cloudflare.com/turnstile/v0/siteverify',false,$ctx);
    if($raw==='')throw new RuntimeException('No pudimos completar la validación anti-spam. Intenta nuevamente.');
  }
  $result=json_decode($raw,true);if(!is_array($result)||empty($result['success']))throw new RuntimeException('La validación anti-spam no fue aprobada. Actualiza la página e inténtalo nuevamente.');
  $action=trim((string)($result['action']??''));if($action!==''&&$action!=='public_contact')throw new RuntimeException('La validación de seguridad no corresponde a este formulario.');
  $expected=trim((string)($cfg['public_turnstile_hostname']??''));$actual=trim((string)($result['hostname']??''));if($expected!==''&&!hash_equals(strtolower($expected),strtolower($actual)))throw new RuntimeException('La validación de seguridad proviene de un dominio no autorizado.');
}
function userAvatarUrl(array $u): string { $v=trim((string)($u['avatar_path']??'')); return $v!==''?$v:''; }
function ensureRuntimeSchema(): void { try{$pdo=appDb();zynkoEnsurePlanSchema($pdo);OpenAIProviderService::ensureSchema($pdo);$cols=$pdo->query("SHOW COLUMNS FROM users LIKE 'avatar_path'")->fetch();if(!$cols)$pdo->exec("ALTER TABLE users ADD avatar_path VARCHAR(500) NULL AFTER email");
