function zynkoTrackPublicVisit(): void {
  try{
    $ua=mb_substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,500);
    if($ua===''||preg_match('/bot|crawler|spider|slurp|bingpreview|facebookexternalhit|whatsapp|telegrambot|uptime|monitor/i',$ua))return;
    $visitor=preg_replace('/[^a-f0-9]/','',strtolower((string)($_COOKIE['zynko_public_visitor']??'')));
    if(strlen($visitor)!==40){$visitor=bin2hex(random_bytes(20));setcookie('zynko_public_visitor',$visitor,['expires'=>time()+31536000,'path'=>'/','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','httponly'=>true,'samesite'=>'Lax']);}
    $device='desktop';if(preg_match('/ipad|tablet|kindle|silk/i',$ua))$device='tablet';elseif(preg_match('/mobi|android|iphone|ipod|windows phone/i',$ua))$device='mobile';
    $browser='Otro';if(preg_match('/Edg\//i',$ua))$browser='Edge';elseif(preg_match('/OPR\//i',$ua))$browser='Opera';elseif(preg_match('/Chrome\//i',$ua))$browser='Chrome';elseif(preg_match('/Firefox\//i',$ua))$browser='Firefox';elseif(preg_match('/Safari\//i',$ua))$browser='Safari';
    $refHost='';$ref=trim((string)($_SERVER['HTTP_REFERER']??''));if($ref!=='')$refHost=strtolower((string)(parse_url($ref,PHP_URL_HOST)??''));$currentHost=strtolower(preg_replace('/:\d+$/','',(string)($_SERVER['HTTP_HOST']??'')));if($refHost===$currentHost)$refHost='Directo / interno';elseif($refHost==='')$refHost='Directo';
    $ip=trim((string)($_SERVER['REMOTE_ADDR']??''));$env=envConfig($GLOBALS['root'].'/.env');$salt=(string)($env['APP_KEY']??'zynko-public-analytics');$ipHash=$ip!==''?hash('sha256',$salt.'|'.$ip):null;
    $q=appDb()->prepare('INSERT INTO public_site_visits(visitor_id,ip_hash,referrer_host,device_type,browser,user_agent) VALUES(?,?,?,?,?,?)');$q->execute([$visitor,$ipHash,$refHost?:null,$device,$browser,$ua?:null]);
  }catch(Throwable $e){}
}
