    $name=mb_substr(trim((string)($_POST['company_name']??'')),0,160);$business=mb_substr(trim((string)($_POST['business_id']??'')),0,80);$phone=mb_substr(trim((string)($_POST['contact_phone']??'')),0,50);$ownerName=mb_substr(trim((string)($_POST['owner_name']??'')),0,160);$email=strtolower(trim((string)($_POST['owner_email']??'')));$pass=(string)($_POST['owner_password']??'');$plan=(int)($_POST['plan_id']??0);
    if(mb_strlen($name)<2)throw new RuntimeException('Ingresa el nombre de la empresa.');if(mb_strlen($ownerName)<3)throw new RuntimeException('Ingresa el nombre del usuario principal.');if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Ingresa un correo válido.');if(strlen($pass)<8)throw new RuntimeException('La contraseña temporal debe tener al menos 8 caracteres.');
    $q=$pdo->prepare('SELECT id FROM users WHERE email=? LIMIT 1');$q->execute([$email]);if($q->fetchColumn())throw new RuntimeException('Ese correo ya está registrado en ZYNKO.');if($business!==''){$q=$pdo->prepare('SELECT id FROM tenants WHERE business_id=? LIMIT 1');$q->execute([$business]);if($q->fetchColumn())throw new RuntimeException('La identificación fiscal ya pertenece a otra empresa.');}
